1	import { TransactionAuthorizationFailure } from "./transaction-authorization.js";
2	/** Source-private loopback fixture. Never selected by installed config/profile
3	 * admission. It exposes actual routes, not an incomplete BDP discovery claim. */
4	import { createTransactionSchemaHttp } from "./transaction-schema-http.js";
5	import { createNodeHttpDisconnectSignal } from "./node-http-disconnect.js";
6	import { pumpTransactionChanges, pumpTransactionEvents } from "./transaction-sse.js";
7	import { ScopeServerOperationAbortedError } from "./read-request.js";
8	import { createServer, type IncomingMessage, ServerResponse } from "node:http";
9	import path from "node:path";
10	import { Socket } from "node:net";
11	import { TextDecoder } from "node:util";
12	import { stringifyJsonValue, type TypeDescriptor } from "@bdp/protocol";
13	import type { ContractArtifactLimits } from "./installed-contract-artifact.js";
14	import { captureTransactionRuntimeConfiguration } from "./transaction-runtime-configuration.js";
15	import type { HttpResponse } from "./index.js";
16	import { normalizationSafeRawRequestPath } from "./node-http-target.js";
17	import { openTransactionStore, type TransactionReadContext } from "./transaction-store.js";
18	import { TRANSACTION_RUNTIME_LIMITS } from "./transaction-batch.js";
19	import {
20	  createTransactionService,
21	  TransactionStreamCapacityError,
22	  type TransactionServiceOptions,
23	} from "./transaction-service.js";
24	import {
25	  createTransactionHttpHandler,
26	  transactionHttpProblem,
27	  TRANSACTION_HTTP_TARGET_BYTES,
28	  type TransactionReceivedBody,
29	  type TransactionHttpResult,
30	} from "./transaction-http.js";
31	
32	export interface TransactionRuntimeOptions {
33	  /** Stable configured identity; omission is a disposable same-port fixture only. */
34	  readonly scope?: string;
35	  readonly authorityMode?: "listener" | "canonical";
36	  readonly directory: string;
37	  readonly create: boolean;
38	  readonly port: number;
39	  readonly types?: readonly TypeDescriptor[];
40	  /** Plain child-process data. Compiled in this module instance, never transported branded. */
41	  readonly artifacts?: {
42	    readonly descriptors: readonly { readonly retrievalUri: string; readonly utf8: string }[];
43	    readonly schemas: readonly { readonly retrievalUri: string; readonly utf8: string }[];
44	    readonly limits: ContractArtifactLimits;
45	  };
46	  readonly credentials: readonly {
47	    readonly token: string;
48	    readonly principal: string;
49	    readonly canMutate: boolean;
50	  }[];
51	}
52	export interface TransactionRuntimeTestSeams {
53	  readonly scheduler?: TransactionServiceOptions["scheduler"];
54	  readonly clock?: () => number;
55	  /** Direct transaction.operations only; sequence.operations retains its own32 bound. */
56	  readonly maximumOperations?: number;
57	  readonly comparison?: TransactionServiceOptions["comparison"];
58	  readonly minimumReads?: TransactionServiceOptions["minimumReads"];
59	  readonly receiptMaximumItems?: number;
60	  /** Store timer isolation for clock-advancing HTTP tests; default unchanged. */
61	  readonly maintenanceIntervalMs?: number;
62	  /** Source-only deadline observations. Any supplied seam suppresses metadata. */
63	  readonly transport?: Partial<
64	    Record<"requestTimeout" | "headersTimeout" | "timeout" | "keepAliveTimeout", number>
65	  >;
66	}
67	async function receive(request: IncomingMessage): Promise<TransactionReceivedBody> {
68	  const length = request.headers["content-length"];
69	  if (
70	    length !== undefined &&
71	    (!/^\d+$/.test(length) || Number(length) > TRANSACTION_RUNTIME_LIMITS.requestBodyBytes)
72	  )
73	    return { failure: "request-too-large" };
74	  const chunks: Buffer[] = [];
75	  let total = 0;
76	  for await (const chunk of request.iterator({ destroyOnReturn: false })) {
77	    total += chunk.length;
78	    if (total > TRANSACTION_RUNTIME_LIMITS.requestBodyBytes)
79	      return { failure: "request-too-large" };
80	    chunks.push(chunk);
81	  }
82	  try {
83	    return { text: new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks)) };
84	  } catch {
85	    return { failure: "malformed-request" };
86	  }
87	}
88	function deliver(response: ServerResponse, selected: HttpResponse, raw?: string): void {
89	  if (response.destroyed) return;
90	  const bytes =
91	    raw ?? (selected.body === undefined ? undefined : stringifyJsonValue(selected.body));
92	  selected.headers.set("x-bdp-development", "non-attesting");
93	  if (bytes !== undefined) selected.headers.set("content-length", String(Buffer.byteLength(bytes)));
94	  response.writeHead(selected.status, Object.fromEntries(selected.headers));
95	  response.end(response.req.method === "HEAD" ? undefined : bytes);
96	}
97	export async function startTransactionRuntime(
98	  options: TransactionRuntimeOptions,
99	  seams: TransactionRuntimeTestSeams = {},
100	) {
101	  const captured = captureTransactionRuntimeConfiguration(options, seams);
102	  const { settings, configuredScope, contracts, types } = captured;
103	  const capturedSeams = captured.seams;
104	  let service: ReturnType<typeof createTransactionService> | undefined;
105	  let handler: ReturnType<typeof createTransactionHttpHandler> | undefined;
106	  let schemas: ReturnType<typeof createTransactionSchemaHttp> | undefined;
107	  let configurationMetadata: ReturnType<typeof captured.metadata>;
108	  let listenUrl = "";
109	  let scope = "",
110	    closing = false;
111	  const pending = new Set<Promise<void>>();
112	  // Retain only the first unexpected live fault. Wire cancellation remains
113	  // silent; close surfaces the original cause through existing aggregation.
114	  let firstStreamFault: { readonly cause: unknown } | undefined;
115	  const handle = async (request: IncomingMessage, response: ServerResponse): Promise<void> => {
116	    let signal: AbortSignal | undefined;
117	    let streamContext: TransactionReadContext | undefined;
118	    try {
119	      if (closing || !handler) {
120	        deliver(response, transactionHttpProblem("temporarily-unavailable"));
121	        return;
122	      }
123	      const raw = request.url ?? "";
124	      if (request.method === "POST" && Buffer.byteLength(raw) > TRANSACTION_HTTP_TARGET_BYTES) {
125	        deliver(response, transactionHttpProblem("request-too-large"));
126	        return;
127	      }
128	      if (
129	        normalizationSafeRawRequestPath(raw) === undefined ||
130	        !raw.startsWith("/") ||
131	        raw.startsWith("//") ||
132	        request.headers.host !==
133	          new URL(captured.authorityMode === "canonical" ? scope : listenUrl).host
134	      ) {
135	        deliver(response, transactionHttpProblem("malformed-request"));
136	        return;
137	      }
138	      const url = new URL(raw, scope);
139	      const methodFailure = handler.methodResponse(url, request.method ?? "GET");
140	      if (methodFailure) {
141	        // Refused bodies are not consumed and cannot keep this connection alive.
142	        methodFailure.headers.set("connection", "close");
143	        deliver(response, methodFailure);
144	        return;
145	      }
146	      const headers = new Headers();
147	      for (let i = 0; i < request.rawHeaders.length; i += 2)
148	        headers.append(request.rawHeaders[i] ?? "", request.rawHeaders[i + 1] ?? "");
149	      const supplied = Buffer.from(headers.get("authorization") ?? "");
150	      const authorization = captured.authenticate(supplied);
151	      signal = createNodeHttpDisconnectSignal(request, response);
152	      const input = new Request(url, { method: request.method ?? "GET", headers, signal });
153	      const lastEventIds: string[] = [];
154	      for (let i = 0; i < request.rawHeaders.length; i += 2)
155	        if (request.rawHeaders[i]?.toLowerCase() === "last-event-id")
156	          lastEventIds.push(request.rawHeaders[i + 1] ?? "");
157	      const body = request.method === "POST" ? await receive(request) : { text: "" };
158	      if (closing || response.destroyed) {
159	        deliver(response, transactionHttpProblem("temporarily-unavailable"));
160	        return;
161	      }
162	      // This fixture has no CORS policy. Origin is a transport refusal, not a
163	      // mutation permission synthesized from carried provenance.
164	      if (headers.has("origin")) {
165	        deliver(response, transactionHttpProblem("forbidden"));
166	        return;
167	      }
168	      if ("failure" in body) response.setHeader("connection", "close");
169	      const schema = await schemas?.(input, authorization);
170	      if (schema) {
171	        deliver(response, schema.response, schema.raw);
172	        return;
173	      }
174	      let selected: TransactionHttpResult | undefined = await handler.handle(
175	        input,
176	        authorization,
177	        body,
178	        lastEventIds,
179	      );
180	      if (selected.kind === "finite") deliver(response, selected);
181	      else {
182	        if (!captured.liveStreamsAvailable) {
183	          deliver(response, {
184	            status: 500,
185	            headers: new Headers({
186	              "cache-control": "private, no-store",
187	              "x-bdp-development-limit": "stream-transport-timing",
188	            }),
189	          });
190	          return;
191	        }
192	        const activeService = service!;
193	        streamContext = selected.context;
194	        await activeService.stream(
195	          async (streamSignal) => {
196	            try {
197	              streamSignal.throwIfAborted();
198	              if (!selected || selected.kind === "finite")
199	                throw new Error("missing stream selection");
200	              response.writeHead(selected.status, Object.fromEntries(selected.headers));
201	              response.flushHeaders();
202	              const pumping =
203	                selected.kind === "changefeed-stream"
204	                  ? pumpTransactionChanges(
205	                      response,
206	                      selected.page,
207	                      async (after, nextSignal) => {
208	                        const observed = await activeService.changes(
209	                          { after },
210	                          undefined,
211	                          nextSignal,
212	                        );
213	                        if (observed.kind !== "page")
214	                          throw new Error("changefeed stream lost serving entry");
215	                        return observed.page;
216	                      },
217	                      streamSignal,
218	                      settings.changefeedStream,
219	                    )
220	                  : pumpTransactionEvents(
221	                      response,
222	                      selected.packet,
223	                      (scan, nextSignal) => activeService.nextEvents(scan, nextSignal),
224	                      streamSignal,
225	                      settings.changefeedStream,
226	                    );
227	              // Transfer the initial packet into the pump; do not retain the HTTP
228	              // result/group body for the lifetime of the live stream.
229	              selected = undefined;
230	              await pumping;
231	            } catch (error) {
232	              // Capture before destroy() turns a genuine fault into a disconnect.
233	              if (
234	                response.headersSent &&
235	                !streamSignal.aborted &&
236	                !response.destroyed &&
237	                !firstStreamFault
238	              )
239	                firstStreamFault = { cause: error };
240	              throw error;
