            result.status === "rejected" ? [result.reason] : [],
          );
          if (failures.length)
            throw new AggregateError(failures, "installed shutdown cleanup failed");
        })().catch((error) => {
          completion = undefined;
          throw error;
        });
      }
      return completion;
    },
  });
