        authorityMode,
        runtimeConfigurationIdentity,
        artifactIdentity: contracts.identity,
        policyIdentity,
        authenticationIdentity,
        scope,
        profile: "transactional" as const,
        history: false as const,
        claimEligible: false as const,
      });
